import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] rel = new long[n];
        for (int i = 0; i < n; i++) rel[i] = nextLong();
        // Pack (availability, reliability) into one long; both are below 2^21.
        long[] s = new long[n];
        for (int i = 0; i < n; i++) s[i] = (nextLong() << 21) | rel[i];
        Arrays.sort(s);
        // Each availability as the minimum: take every server at least that available.
        long total = 0, answer = 0;
        for (int i = n - 1; i >= 0; i--) {
            total += s[i] & ((1 << 21) - 1);
            answer = Math.max(answer, (s[i] >> 21) * total);
        }
        System.out.println(answer % 1000000007);
    }
}

